use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut jobs = input.as_array().unwrap();
    jobs.sort_by_key(|job| job.get("arrival").unwrap().as_i64().unwrap());

    let mut current_finish = jobs[0].get("arrival").unwrap().as_i64().unwrap();
    let mut current_time = current_finish;

    for job in jobs {
        let arrival = job.get("arrival").unwrap().as_i64().unwrap();
        let duration = job.get("duration").unwrap().as_i64().unwrap();

        let finish = current_time + duration;
        current_time = std::cmp::max(current_time, arrival);
        current_finish = std::cmp::max(current_finish, finish);
    }

    json!({
        "finish": current_finish,
        "time": current_time
    })
}
